package httpserver
import("context";"net/http";"strconv";"time")
func(a AdminHandler)Claims(w http.ResponseWriter,r *http.Request){if !a.authorized(r){writeJSON(w,401,map[string]string{"error":"unauthorized"});return};limit,_:=strconv.Atoi(r.URL.Query().Get("limit"));if limit<1||limit>100{limit=50};ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second);defer cancel();rows,err:=a.DB.QueryContext(ctx,`SELECT c.id::text,p.e164,c.claimant_name,c.claimant_type::text,c.contact_email,c.status::text,c.created_at FROM phone_claims c JOIN phone_numbers p ON p.id=c.phone_number_id ORDER BY c.created_at DESC LIMIT $1`,limit);if err!=nil{writeJSON(w,500,map[string]string{"error":"internal_error"});return};defer rows.Close();items:=[]map[string]any{};for rows.Next(){var id,e164,name,kind,status string;var email *string;var created time.Time;if rows.Scan(&id,&e164,&name,&kind,&email,&status,&created)==nil{items=append(items,map[string]any{"id":id,"e164":e164,"name":name,"kind":kind,"email":email,"status":status,"created_at":created})}};writeJSON(w,200,map[string]any{"data":items})}
